  DialogComboboxContent,
  DialogComboboxOptionList,
  DialogComboboxOptionListCheckboxItem,
  DialogComboboxOptionListSelectItem,
  DialogComboboxTrigger,
} from '@databricks/design-system';

export const LabelSchemaInputCategorical = ({
  input,
  value,
  onChange,
  componentId,
  label,
  disabled,
}: {
  input: { options: string[]; multi_select?: boolean };
  value: string | string[] | null | undefined;
  onChange: (value: string | string[]) => void;
  componentId: string;
  label: string;
  disabled?: boolean;
}) => {
  const isMultiSelect = Boolean(input.multi_select);

  const selectedValues = Array.isArray(value) ? value : value ? [value] : [];

  const toggleMultiSelectValue = (option: string) => {
    if (selectedValues.includes(option)) {
      onChange(selectedValues.filter((selected) => selected !== option));
    } else {
      onChange([...selectedValues, option]);
    }
  };

  return (
    <DialogCombobox
      componentId={componentId}
      label={label}
      multiSelect={isMultiSelect}
      value={selectedValues}
    >
      <DialogComboboxTrigger aria-label={label} withInlineLabel={false} disabled={disabled} allowClear={false} />
      <DialogComboboxContent>
        <DialogComboboxOptionList>
          {input.options.map((option) =>
            isMultiSelect ? (
              <DialogComboboxOptionListCheckboxItem
                key={option}
                value={option}
                checked={selectedValues.includes(option)}
                onChange={() => toggleMultiSelectValue(option)}
              >
                {option}
              </DialogComboboxOptionListCheckboxItem>
            ) : (
              <DialogComboboxOptionListSelectItem
                key={option}
                value={option}
                checked={selectedValues.includes(option)}
                onChange={() => onChange(option)}
              >
                {option}
              </DialogComboboxOptionListSelectItem>
            ),
          )}
        </DialogComboboxOptionList>
      </DialogComboboxContent>
    </DialogCombobox>
  );
};
