export const LabelSchemaInputRenderer = ({
  input,
  value,
  onChange,
  componentId,
  label,
  disabled,
}: {
  input: LabelSchemaInput;
  value: any;
  onChange: (value: any) => void;
  componentId: string;
  label?: string;
  disabled?: boolean;
  instruction?: string;
}) => {
  if (input.pass_fail) {
    return (
      <LabelSchemaInputPassFail
        input={input.pass_fail}
        value={value}
        onChange={onChange}
        componentId={componentId}
        disabled={disabled}
      />
    );
  }

  if (input.numeric) {
    return (
      <LabelSchemaInputNumeric
        input={input.numeric}
        value={value}
        onChange={onChange}
        componentId={componentId}
        disabled={disabled}
      />
    );
  }

  if (input.categorical) {
    return (
      <LabelSchemaInputCategorical
        input={input.categorical}
        value={value}
        onChange={onChange}
        componentId={componentId}
        label={label ?? ''}
        disabled={disabled}
      />
    );
  }

  if (input.text) {
    return (
      <Input
        componentId={componentId}
        value={value ?? ''}
        disabled={disabled}
        maxLength={input.text.max_length}
        onChange={(event) => onChange(event.target.value)}
      />
    );
  }

  return <div role="alert">Invalid label schema input</div>;
};
